using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Sigov.Application.Defesa;
using Sigov.Web.Models.Defesa;
namespace Sigov.Web.Controllers;

[Authorize,Route("Defesa"),Route("DefesaCivil")]
public sealed class DefesaController(IDefesaRepository repository,IAuthorizationService authorization):Controller
{
 private static readonly IReadOnlyDictionary<string,(string Title,string View,string Manage)> Resources=new Dictionary<string,(string,string,string)>(StringComparer.OrdinalIgnoreCase){["Agentes"]=("Agentes e guardas","DEFESA_AGENTE_VIEW","DEFESA_AGENTE_MANAGE"),["Equipes"]=("Equipes operacionais","DEFESA_CIVIL_OCORRENCIA_VIEW","DEFESA_CIVIL_RESPOSTA_MANAGE"),["Recursos"]=("Recursos e embarcações","DEFESA_CIVIL_OCORRENCIA_VIEW","DEFESA_CIVIL_RECURSO_MANAGE"),["AreasRisco"]=("Áreas e cenários de risco","DEFESA_CIVIL_RISCO_VIEW","DEFESA_CIVIL_RISCO_MANAGE"),["Ocorrencias"]=("Ocorrências","DEFESA_CIVIL_OCORRENCIA_VIEW","DEFESA_CIVIL_OCORRENCIA_MANAGE"),["Acionamentos"]=("Acionamentos","DEFESA_ACIONAMENTO_VIEW","DEFESA_ACIONAMENTO_MANAGE"),["Vistorias"]=("Vistorias preventivas","DEFESA_VISTORIA_VIEW","DEFESA_VISTORIA_MANAGE"),["Abrigos"]=("Abrigos temporários","DEFESA_CIVIL_ABRIGO_VIEW","DEFESA_CIVIL_ABRIGO_MANAGE"),["Atendimentos"]=("Atendimentos emergenciais","DEFESA_ATENDIMENTO_VIEW","DEFESA_ATENDIMENTO_MANAGE"),["Rondas"]=("Rondas e patrulhamentos","DEFESA_RONDA_VIEW","DEFESA_RONDA_MANAGE"),["OrdensServico"]=("Ordens de serviço","DEFESA_OS_VIEW","DEFESA_OS_MANAGE"),["Notificacoes"]=("Notificações preventivas","DEFESA_NOTIFICACAO_VIEW","DEFESA_NOTIFICACAO_MANAGE"),["PlanosContingencia"]=("Planos de contingência","DEFESA_CIVIL_PLANO_VIEW","DEFESA_CIVIL_PLANO_MANAGE"),["Auditoria"]=("Auditoria operacional","DEFESA_AUDITORIA_VIEW","DEFESA_AUDITORIA_VIEW"),["CenariosRisco"]=("Cenários de risco","DEFESA_CIVIL_RISCO_VIEW","DEFESA_CIVIL_RISCO_MANAGE"),["RotasEvacuacao"]=("Rotas de evacuação","DEFESA_CIVIL_PLANO_VIEW","DEFESA_CIVIL_PLANO_MANAGE"),["Resposta"]=("Resposta a ocorrências","DEFESA_CIVIL_OCORRENCIA_VIEW","DEFESA_CIVIL_RESPOSTA_MANAGE"),["Estoques"]=("Estoques de emergência","DEFESA_CIVIL_ABRIGO_VIEW","DEFESA_CIVIL_ESTOQUE_MANAGE"),["Doacoes"]=("Doações","DEFESA_CIVIL_ABRIGO_VIEW","DEFESA_CIVIL_ESTOQUE_MANAGE"),["Alertas"]=("Alertas públicos","DEFESA_CIVIL_DASHBOARD_VIEW","DEFESA_CIVIL_ALERTA_MANAGE"),["FontesMonitoramento"]=("Fontes de monitoramento","DEFESA_CIVIL_DASHBOARD_VIEW","DEFESA_CIVIL_ALERTA_MANAGE"),["Comunicacoes"]=("Comunicações à população","DEFESA_CIVIL_DASHBOARD_VIEW","DEFESA_CIVIL_ALERTA_MANAGE"),["Evidencias"]=("Evidências transversais","DEFESA_CIVIL_RISCO_VIEW","DEFESA_CIVIL_RISCO_MANAGE"),["Ocupacao"]=("Ocupação de abrigos","DEFESA_CIVIL_ABRIGO_VIEW","DEFESA_CIVIL_ABRIGO_MANAGE")};
 [HttpGet(""),HttpGet("Dashboard"),Authorize(Policy="DEFESA_CIVIL_DASHBOARD_VIEW")]public async Task<IActionResult> Dashboard(CancellationToken ct)=>View(await repository.DashboardAsync(Context(),ct));
 [HttpGet("{recurso}")]public async Task<IActionResult> Lista(string recurso,string? busca,string? status,DateOnly? inicio,DateOnly? fim,int pagina,CancellationToken ct){var m=Meta(recurso);if(!await Allowed(m.View))return Forbid();var f=new DefesaFiltro(busca,status,inicio,fim,Math.Max(1,pagina));return View("Lista",new DefesaListaViewModel(m.Title,recurso,await repository.ListarAsync(Context(),recurso,f,ct),f));}
 [HttpGet("{recurso}/Novo")]public async Task<IActionResult> Novo(string recurso,CancellationToken ct){var m=Meta(recurso);if(!await Allowed(m.Manage)||recurso.Equals("Auditoria",StringComparison.OrdinalIgnoreCase))return Forbid();return View("Form",await Form(m.Title,recurso,new(),ct));}
 [HttpGet("{recurso}/{id:long}")]public async Task<IActionResult> Detalhes(string recurso,long id,CancellationToken ct){var m=Meta(recurso);if(!await Allowed(m.View))return Forbid();var registro=await repository.ObterAsync(Context(),recurso,id,ct);return registro is null?NotFound():View("Details",new DefesaDetailsViewModel(m.Title,recurso,id,registro));}
 [HttpGet("{recurso}/{id:long}/Editar")]public async Task<IActionResult> Editar(string recurso,long id,CancellationToken ct){var m=Meta(recurso);if(!await Allowed(m.Manage)||recurso.Equals("Auditoria",StringComparison.OrdinalIgnoreCase))return Forbid();var registro=await repository.ObterAsync(Context(),recurso,id,ct);return registro is null?NotFound():View("Form",await Form(m.Title,recurso,registro,ct,id));}
 [HttpPost("{recurso}/Salvar"),ValidateAntiForgeryToken]public async Task<IActionResult> Salvar(string recurso,long? id,DefesaRegistroRequest registro,CancellationToken ct){var m=Meta(recurso);if(!await Allowed(m.Manage))return Forbid();ValidateRules(recurso,registro);if(!ModelState.IsValid)return View("Form",await Form(m.Title,recurso,registro,ct,id));try{await repository.SalvarAsync(Context(),recurso,registro,id,ct);TempData["Success"]=id.HasValue?"Registro atualizado e auditado.":"Registro salvo com auditoria e finalidade operacional.";return RedirectToAction(nameof(Lista),new{recurso});}catch(ArgumentException ex){ModelState.AddModelError("",ex.Message);return View("Form",await Form(m.Title,recurso,registro,ct,id));}}
 [HttpPost("{recurso}/{id:long}/Excluir"),ValidateAntiForgeryToken]public async Task<IActionResult> Excluir(string recurso,long id,CancellationToken ct){var m=Meta(recurso);if(!await Allowed(m.Manage))return Forbid();await repository.ExcluirAsync(Context(),recurso,id,ct);TempData["Success"]="Registro excluído e auditado.";return RedirectToAction(nameof(Lista),new{recurso});}

 [HttpGet("Ocorrencias/Create")] public IActionResult CriarOcorrencia()=>RedirectToAction(nameof(Novo),new{recurso="Ocorrencias"});
 [HttpGet("Abrigos/Ocupacao")] public IActionResult OcupacaoAbrigos()=>RedirectToAction(nameof(Lista),new{recurso="Ocupacao"});
 [HttpGet("Relatorios"),Authorize(Policy="DEFESA_CIVIL_RELATORIO_EXPORT")]public IActionResult Relatorios()=>View();
 [HttpGet("Relatorios/{recurso}.csv"),Authorize(Policy="DEFESA_CIVIL_RELATORIO_EXPORT")]public async Task<IActionResult> Csv(string recurso,string? busca,string? status,DateOnly? inicio,DateOnly? fim,CancellationToken ct)=>File(await repository.CsvAsync(Context(),recurso,new(busca,status,inicio,fim),ct),"text/csv; charset=utf-8",$"defesa-{recurso}-{DateTime.UtcNow:yyyyMMdd}.csv");
 private async Task<DefesaFormViewModel> Form(string title,string recurso,DefesaRegistroRequest registro,CancellationToken ct,long? id=null){var d=new Dictionary<string,IReadOnlyList<DefesaOpcao>>();foreach(var type in new[]{"Agentes","Equipes","AreasRisco","Ocorrencias","Abrigos","Vistorias","CenariosRisco","PlanosContingencia","Recursos","Alertas","Usuarios","Unidades","Pessoas","EvidenciasCanonicas"})if(!type.Equals(recurso,StringComparison.OrdinalIgnoreCase))d[type]=await repository.OpcoesAsync(Context(),type,true,ct);return new(title,recurso,id,registro,d);}
 private void ValidateRules(string recurso,DefesaRegistroRequest r){ValidateCatalogs(recurso,r);string? F(string n)=>r.Campos.GetValueOrDefault(n);void Req(params string[] fs){foreach(var f in fs)if(string.IsNullOrWhiteSpace(F(f)))ModelState.AddModelError($"Registro.Campos[{f}]",$"Informe {f.Replace('_',' ')}.");}void Dates(string a,string b){if(DateTime.TryParse(F(a),out var x)&&DateTime.TryParse(F(b),out var y)&&y<x)ModelState.AddModelError($"Registro.Campos[{b}]","A data final não pode anteceder a inicial.");}switch(recurso.ToUpperInvariant()){case"AGENTES":Req("cpf","tipo_agente","data_inicio");Dates("data_inicio","data_fim");break;case"EQUIPES":Req("tipo","responsavel_usuario_id");break;case"RECURSOS":Req("tipo","quantidade","quantidade_mobilizada");break;case"AREASRISCO":Req("tipo","nivel_risco","bairro");if(F("nivel_risco")=="CRITICO"&&r.Descricao.Trim().Length<30)ModelState.AddModelError(nameof(r.Descricao),"Área crítica exige descrição detalhada (mínimo de 30 caracteres).");Coordinates();break;case"OCORRENCIAS":Req("tipo","severidade","nivel_resposta","local","inicio_em");Dates("inicio_em","encerrada_em");if(r.Status=="ENCERRADA")Req("encerrada_em");break;case"ACIONAMENTOS":Req("ocorrencia_id","equipe_id","data_hora_acionamento");Dates("data_hora_acionamento","data_hora_chegada");Dates("data_hora_chegada","data_hora_encerramento");break;case"VISTORIAS":Req("tipo_vistoria","agente_responsavel_id","data_vistoria","endereco","bairro","recomendacoes");Dates("data_vistoria","prazo_regularizacao");break;case"ABRIGOS":Req("endereco","bairro","capacidade","vagas_reservadas","responsavel_usuario_id");if(int.TryParse(F("capacidade"),out var total)&&int.TryParse(F("vagas_reservadas"),out var reservadas)&&reservadas>total)ModelState.AddModelError("","As vagas reservadas não podem superar a capacidade.");break;case"ATENDIMENTOS":Req("quantidade_pessoas","tipo_apoio","data_atendimento");Quantities();break;case"RONDAS":Req("equipe_id","agente_responsavel_id","data_hora_inicio","tipo_ronda");Dates("data_hora_inicio","data_hora_fim");if(r.Status=="CONCLUIDA")Req("resumo");break;case"ORDENSSERVICO":Req("tipo_servico","solicitante","data_abertura","prioridade");Dates("data_abertura","data_conclusao");if(r.Status=="CONCLUIDA")Req("resultado");break;case"NOTIFICACOES":Req("endereco","data_emissao","motivo","recomendacao");Dates("data_emissao","prazo_atendimento");break;case"PLANOSCONTINGENCIA":Req("cenario_risco_id","responsavel_usuario_id","vigencia_inicio","vigencia_fim");Dates("vigencia_inicio","vigencia_fim");if(r.Status is "APROVADO" or "PUBLICADO")Req("aprovado_por","aprovado_em");break;case"CENARIOSRISCO":Req("area_risco_id","tipo","severidade","probabilidade");break;case"ROTASEVACUACAO":Req("plano_id","origem","destino");break;case"RESPOSTA":Req("ocorrencia_id","acao","inicio_em");Dates("inicio_em","fim_em");break;case"ESTOQUES":Req("saldo","nivel_critico","unidade_medida");break;case"DOACOES":Req("origem","tipo","quantidade");break;case"ALERTAS":Req("area_risco_id","severidade","mensagem","valido_de","valido_ate","canal");Dates("valido_de","valido_ate");if(r.Status=="PUBLICADO")Req("aprovado_por","publicado_em");break;case"FONTESMONITORAMENTO":Req("tipo","identificacao","periodicidade_minutos");break;case"COMUNICACOES":Req("canal","mensagem");break;case"OCUPACAO":Req("abrigo_id","pessoa_id","entrada_em");Dates("entrada_em","saida_em");break;case"EVIDENCIAS":Req("evidencia_id","contexto_tipo","contexto_id");break;}void Coordinates(){if(decimal.TryParse(F("latitude"),out var lat)&&(lat is < -90 or > 90))ModelState.AddModelError("","Latitude deve estar entre -90 e 90.");if(decimal.TryParse(F("longitude"),out var lon)&&(lon is < -180 or > 180))ModelState.AddModelError("","Longitude deve estar entre -180 e 180.");}void Quantities(){if(int.TryParse(F("quantidade_pessoas"),out var t)){if(t<1)ModelState.AddModelError("","A quantidade de pessoas deve ser ao menos 1.");foreach(var k in new[]{"quantidade_criancas","quantidade_idosos"})if(int.TryParse(F(k),out var q)&&(q<0||q>t))ModelState.AddModelError("",$"{k.Replace('_',' ')} deve estar entre zero e o total.");}}}
 private void ValidateCatalogs(string recurso,DefesaRegistroRequest r)
 {
  var statuses=new Dictionary<string,string[]>(StringComparer.OrdinalIgnoreCase){
   ["Agentes"]=["ATIVO","INATIVO"],["Equipes"]=["ATIVA","INATIVA"],["Recursos"]=["DISPONIVEL","EM_USO","MANUTENCAO","INATIVO"],
   ["AreasRisco"]=["ATIVA","MONITORADA","INATIVA"],["Ocorrencias"]=["ABERTA","EM_ATENDIMENTO","ENCERRADA","CANCELADA"],
   ["Acionamentos"]=["ACIONADO","EM_DESLOCAMENTO","NO_LOCAL","ENCERRADO","CANCELADO"],["Vistorias"]=["PENDENTE","REALIZADA","CANCELADA"],
   ["Abrigos"]=["ATIVO","INATIVO"],["Atendimentos"]=["ATIVO","ENCERRADO","CANCELADO"],["Rondas"]=["PLANEJADA","EM_ANDAMENTO","CONCLUIDA","CANCELADA"],
   ["OrdensServico"]=["ABERTA","EM_ANDAMENTO","CONCLUIDA","CANCELADA"],["Notificacoes"]=["PENDENTE","ATENDIDA","VENCIDA","CANCELADA"],["PlanosContingencia"]=["RASCUNHO","EM_APROVACAO","APROVADO","PUBLICADO","INATIVO"],["CenariosRisco"]=["ATIVO","INATIVO"],["RotasEvacuacao"]=["ATIVA","INATIVA"],["Resposta"]=["EM_ANDAMENTO","CONCLUIDA","CANCELADA"],["Estoques"]=["ATIVO","INATIVO"],["Doacoes"]=["RECEBIDA","DESTINADA","PRESTADA","CANCELADA"],["Alertas"]=["RASCUNHO","APROVADO","PUBLICADO","EXPIRADO","CANCELADO"],["FontesMonitoramento"]=["ATIVA","DESATUALIZADA","INDISPONIVEL","INATIVA"],["Comunicacoes"]=["PENDENTE","PUBLICADA","ERRO","CANCELADA"],["Evidencias"]=["ATIVA","INATIVA"],["Ocupacao"]=["ABRIGADA","ENCERRADA"]};
  if(!statuses.TryGetValue(recurso,out var allowed)||!allowed.Contains(r.Status,StringComparer.Ordinal))ModelState.AddModelError("Registro.Status","Selecione um status válido para este recurso.");
  var catalogs=new Dictionary<string,string[]>(StringComparer.Ordinal){["tipo_agente"]=["DEFESA_CIVIL","GUARDA_MUNICIPAL","APOIO"],["tipo_risco"]=["ALAGAMENTO","DESLIZAMENTO","INCENDIO","ESTRUTURAL","AMBIENTAL","OUTRO"],["nivel_risco"]=["BAIXO","MEDIO","ALTO","CRITICO"],["prioridade"]=["BAIXA","MEDIA","ALTA","CRITICA"]};
  foreach(var item in catalogs)if(r.Campos.TryGetValue(item.Key,out var value)&&!string.IsNullOrWhiteSpace(value)&&!item.Value.Contains(value,StringComparer.Ordinal))ModelState.AddModelError($"Registro.Campos[{item.Key}]","Seleção inválida.");
  if(recurso.Equals("Recursos",StringComparison.OrdinalIgnoreCase)&&r.Campos.TryGetValue("placa_viatura",out var placa)&&!string.IsNullOrWhiteSpace(placa)&&!System.Text.RegularExpressions.Regex.IsMatch(placa,"^[A-Z]{3}[0-9][A-Z0-9][0-9]{2}$",System.Text.RegularExpressions.RegexOptions.IgnoreCase))ModelState.AddModelError("Registro.Campos[placa_viatura]","Informe uma placa no padrão brasileiro.");
 }
 private DefesaContexto Context(){if(!long.TryParse(User.FindFirst("tenant_id")?.Value,out var t)||!long.TryParse(User.FindFirst("entidade_id")?.Value??User.FindFirst("entity_id")?.Value,out var e)||t<=0||e<=0)throw new UnauthorizedAccessException("Contexto tenant/entidade não resolvido.");return new(t,e,User.Identity?.Name??"sistema");}private async Task<bool> Allowed(string p)=>(await authorization.AuthorizeAsync(User,p)).Succeeded;private static(string Title,string View,string Manage)Meta(string r)=>Resources.TryGetValue(r,out var m)?m:throw new ArgumentException("Recurso inválido.");
}
